// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Assume caller is not the admin (admin is the deployer msg.sender, i.e., address(this))
        vm.assume(caller != address(this));
        // Record owner before the call
        address ownerBefore = c.owner();
        // Drive the contract
        vm.prank(caller);
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
        // The call must revert because only admin can call setOwner
        assertTrue(!success, "Non-admin caller should not be able to change owner");
        // Owner must remain unchanged
        assertTrue(c.owner() == ownerBefore, "Owner should not change after failed call");
    }
}

